{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "채권추심 관련 법 위반 금융관행 피해를 입은 청년 채무자의 권리구제가 서울시 청년정책에서 다루어지는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 청년 기본 조례 제14조제2항은 시장이 「채권의 공정한 추심에 관한 법률」 등 기준을 위반한 금융관행에 피해를 입은 청년 채무자의 권리구제를 위하여 노력하여야 한다고 정하고 있다. 따라서 채권추심 관련 법에서 금지한 방식으로 독촉을 받아 피해를 본 청년 채무자의 권리구제는 서울시 청년정책에서 다루는 사항이다. 다만 이는 시장의 노력 의무를 규정한 것으로, 구체적인 지원 내용·절차·대상 범위는 조례에서 직접 정하지 않는다.",
          "b_ids": "청년:제14조제2항, 청년:제3조제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
